# typed: strict
# frozen_string_literal: true

require 'active_record'
require 'active_record/bitwise/errors'
require 'active_record/bitwise/types'
require 'sorbet-runtime'

module ActiveRecord
  module Bitwise
    module Model
      # Verifies that every generated flag method is safe to define: no clobbering of
      # core ActiveRecord methods, of methods generated by other bitwise columns, or
      # of real database columns.
      module Collisions
        extend T::Sig

        # Suffixes of the three methods generated per flag.
        SUFFIXES = %w[? = !].freeze
        private_constant :SUFFIXES

        # Returns the list of generated method names after checking each for collisions.
        # @param model [T.untyped] The model class being configured.
        # @param column_name [T.any(Symbol, String)]
        # @param mapping [T::Hash[Symbol, Integer]]
        # @param prefix [String]
        # @param suffix [String]
        # @raise [ArgumentError] On a collision with core ActiveRecord::Base methods.
        # @raise [ConfigurationError] On a collision with another bitwise column or a database column.
        # @return [T::Array[String]]
        sig do
          params(model: T.untyped, column_name: Types::Name, mapping: Types::Positions,
                 prefix: String, suffix: String).returns(T::Array[String])
        end
        def self.check!(model, column_name, mapping, prefix, suffix)
          others = other_generated(model, column_name)
          columns = table_columns(model)
          mapping.each_key.flat_map do |key|
            name = "#{prefix}#{key}#{suffix}"
            reject_shadowing!(model, column_name, key, name, columns)
            claim_all!(column_name, key, name, others)
          end
        end

        # Claims the `?`, `=` and `!` methods of one flag.
        # @param column_name [Types::Name]
        # @param key [Symbol]
        # @param name [String] The generated base method name.
        # @param others [Array<String>] Methods generated by other bitwise columns.
        # @return [Array<String>] The claimed method names.
        sig { params(column_name: Types::Name, key: Symbol, name: String, others: T::Array[String]).returns(T::Array[String]) }
        def self.claim_all!(column_name, key, name, others)
          SUFFIXES.map { |ending| claim!(column_name, key, "#{name}#{ending}", others) }
        end
        private_class_method :claim_all!

        # Methods generated by the model's other bitwise columns.
        # @param model [T.untyped]
        # @param column_name [T.any(Symbol, String)]
        # @return [T::Array[String]]
        sig { params(model: T.untyped, column_name: Types::Name).returns(T::Array[String]) }
        def self.other_generated(model, column_name)
          model.bitwise_definitions.flat_map do |column, config|
            column == column_name.to_sym ? [] : Array(config[:generated_methods])
          end
        end
        private_class_method :other_generated

        # Names of the model's real database columns (empty when the table is unavailable).
        # @param model [T.untyped]
        # @return [T::Array[String]]
        sig { params(model: T.untyped).returns(T::Array[String]) }
        def self.table_columns(model)
          model.table_exists? ? model.column_names : []
        rescue StandardError
          []
        end
        private_class_method :table_columns

        # Rejects a flag whose base method name would shadow a column or attribute.
        # @param model [T.untyped]
        # @param column_name [T.any(Symbol, String)]
        # @param key [Symbol]
        # @param name [String] The generated base method name.
        # @param columns [T::Array[String]] Real database columns.
        # @raise [ConfigurationError] When the name shadows a column or attribute.
        # @return [void]
        sig do
          params(model: T.untyped, column_name: Types::Name, key: Symbol, name: String,
                 columns: T::Array[String]).void
        end
        def self.reject_shadowing!(model, column_name, key, name, columns)
          shadowed = name == column_name.to_s || model.bitwise_definitions.key?(name.to_sym) || columns.include?(name)
          return unless shadowed

          raise ConfigurationError,
                "Bitwise column #{column_name} mapping key #{key} would shadow the database column or attribute " \
                "'#{name}'. Use prefix:/suffix: to disambiguate."
        end
        private_class_method :reject_shadowing!

        # Verifies a generated method name is free and returns it.
        # @param column_name [T.any(Symbol, String)]
        # @param key [Symbol]
        # @param method_name [String]
        # @param others [T::Array[String]] Methods generated by other bitwise columns.
        # @raise [ArgumentError] On a collision with core ActiveRecord::Base methods.
        # @raise [ConfigurationError] On a collision with another bitwise column.
        # @return [String] +method_name+.
        sig do
          params(column_name: Types::Name, key: Symbol, method_name: String, others: T::Array[String])
            .returns(String)
        end
        def self.claim!(column_name, key, method_name, others)
          prefix = "Bitwise column #{column_name} mapping key #{key} generates method ##{method_name} "
          if core_method?(method_name)
            raise ArgumentError, "#{prefix}which collides with core ActiveRecord::Base instance methods."
          end

          if others.include?(method_name)
            raise ConfigurationError,
                  "#{prefix}which is already defined by another bitwise column. Use prefix:/suffix: to disambiguate."
          end
          method_name
        end
        private_class_method :claim!

        # Whether ActiveRecord::Base already defines +method_name+ (public, protected or private).
        # @param method_name [String]
        # @return [Boolean]
        sig { params(method_name: String).returns(T::Boolean) }
        def self.core_method?(method_name)
          symbol = method_name.to_sym
          ActiveRecord::Base.method_defined?(symbol) || ActiveRecord::Base.private_method_defined?(symbol)
        end
        private_class_method :core_method?
      end
    end
  end
end
